'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');const S=require('./cleanup-schema.cjs'),B=require('./cleanup-backend.cjs'),F=require('./fixtures.cjs'),X=require('./fence-fixtures.cjs');const root=process.env.PUBLIC_TEST_TMP_ROOT||process.env.RUNNER_TEMP;assert(root&&fs.existsSync(root));const temp=()=>fs.mkdtempSync(path.join(root,'unused-reader-'));
async function prepared(){const f=X.fixture(temp());return {f,b:await B.readTarget(f.c,f.deps)};}
test('actual immutable reader requires positive terminal fence, not absence or owner/DSEQ output',async()=>{const {f,b}=await prepared();assert.equal(b.target.returned_runner_id,991);assert.equal(b.target.no_create_record_sha256,S.hash(b.records.no_create));assert(!Object.hasOwn(b.target,'owner')&&!Object.hasOwn(b.target,'dseq'));assert.equal(b.evidence.length,5);assert.deepEqual(b.phase_inventory,{jit:['NO_WIRE','UNKNOWN','ACK'],lease:['FENCE','NO_CREATE'],lease_bind:[]});assert.deepEqual((await B.handlerHistory(f.c,b,[],f.deps)).wire_clear,{remove:true});});
for(const fault of ['no_terminal','no_intent','no_jit_ack','lease_no_wire','lease_unknown','lease_bind','duplicate','foreign_job','later_attempt','cancelled','timed_out','success','partial'])test('positive reader holds '+fault,async()=>{const f=X.fixture(temp());const all=[...f.items.values()];if(fault==='no_terminal')f.items.delete(all.find(x=>x.name.endsWith('-no_create')).id);else if(fault==='no_intent')f.items.delete(all.find(x=>x.name.endsWith('-fence')).id);else if(fault==='no_jit_ack')f.items.delete(all.find(x=>x.name.endsWith('-jit-j777-ack')).id);else if(fault==='lease_no_wire')f.insert(F.producerRecords(false)[3]);else if(fault==='lease_unknown')f.insert(F.producerRecords(false)[4]);else if(fault==='lease_bind')f.insert(F.producerRecords(false)[6]);else if(fault==='duplicate'){const row=all.find(x=>x.name.endsWith('-fence'));f.items.set(9999,{...row,id:9999});}else if(fault==='foreign_job'){const row=all.find(x=>x.name.endsWith('-fence'));row.name=row.name.replace('j777','j778');}else if(fault==='later_attempt')f.runs.get(12345).run_attempt=2;else if(fault==='partial')f.flags.partial=true;else{f.jobMap.get(777).conclusion=fault;f.jobMap.get(777).steps[0].conclusion=fault;f.runs.get(12345).conclusion=fault;}await assert.rejects(B.readTarget(f.c,f.deps));});
test('actual removal intent/UNKNOWN/ACK persistence is one fixed remove slot and only exact ID',async()=>{const {f,b}=await prepared(),held=[];for(const phase of ['NO_WIRE','UNKNOWN','ACK']){const r=X.removal(f.c,b,phase,held.length?S.hash(held.at(-1).record):null),a=await B.persist(r,f.c,b,held,f.deps);S.ack(a,r);held.push({record:r,artifact_id:a.artifact_id,artifact_digest:a.artifact_digest,body_sha256:S.hash(r)});}assert.equal(held.length,3);assert(held.every(x=>x.record.operation_id==='keydb-qualification-v1-12345-a1-r1-remove'));assert(!Object.keys(held[0].record.details).some(k=>['owner','dseq','config','token'].includes(k)));await assert.rejects(B.persist(held[1].record,f.c,b,held,f.deps));});
test('late create frame or provider lease cannot be normalized into cached NO_CREATE',async()=>{const {f,b}=await prepared();f.insert(F.producerRecords(false)[3]);await assert.rejects(B.renewBundle(f.c,b,f.deps));});
test('prior same-slot UNKNOWN removal blocks replay without any invented close intent',async()=>{const {f,b}=await prepared();const held=[];for(const phase of ['NO_WIRE','UNKNOWN']){const r=X.removal(f.c,b,phase,held.length?S.hash(held[0].record):null),a=await B.persist(r,f.c,b,held,f.deps);held.push({record:r,artifact_id:a.artifact_id,artifact_digest:a.artifact_digest,body_sha256:S.hash(r)});}const h=await B.handlerHistory(f.c,b,[],f.deps);assert.deepEqual(h.wire_clear,{remove:false});});
module.exports={prepared};

test('native positive-fence source must equal exact captured cleanup source version',async()=>{const f=X.fixture(temp());f.c.actor.sdk_sha='c'.repeat(40);await assert.rejects(B.producerNative(f.c.actor.target_locator,f.c.actor,f.deps));assert(!f.calls.some(x=>x.includes('/artifacts')));});
test('fresh full native population refuses an intervening assignment of the acknowledged ID',async()=>{const {f,b}=await prepared();f.jobMap.set(889,{...f.jobMap.get(777),id:889,name:'Unexpected other task',runner_id:991});await assert.rejects(B.renewBundle(f.c,b,f.deps));});
test('executed normal known-DSEQ handler with missing remove history is never ignored',async()=>{const {f,b}=await prepared(),run=f.runs.get(12345),job={...f.jobMap.get(888),id:889,run_id:12345,head_sha:run.head_sha,status:'completed',conclusion:'failure',name:S.PREFIX.normal+S.slot(f.c.actor.target_locator),steps:[{name:S.STEP,number:5,status:'completed',conclusion:'failure',started_at:'2026-10-24T15:00:31Z',completed_at:'2026-10-24T15:00:32Z'}]};f.jobMap.set(889,job);await assert.rejects(B.handlerHistory(f.c,b,[],f.deps));});
